--- Constructs a new gradient object.
---@return PaletteGradient
function PaletteGradient:New()
    ---@type PaletteGradient
    local newGradient = {
        Mode = "Blend",
        ColorKeys = {
            { Time = 0, Value = KColor.White },
            { Time = 1, Value = KColor.White },
        },
        AlphaKeys = {
            { Time = 0, Value = 1},
            { Time = 1, Value = 1 }
        },
    }

    return newGradient
end

