    ["palette_scripts.palette_keyframes"] = function()

local PaletteKeyframes = {}

--- Finds the closest two keyframes relative to `time` and returns them.
---@generic T
---@param keyframes Keyframe<T>[]
---@param time number
---@param defaultValue T
---@return KeyframeSegment
function PaletteKeyframes.FindSegment(keyframes, time, defaultValue)
    if #keyframes == 0 then
        return { Left = defaultValue, Right = defaultValue, Alpha = 1}
    elseif time <= keyframes[1].Time then
        local firstValue = keyframes[1].Value
        return { Left = firstValue, Right = firstValue, Alpha = 1}
    elseif time >= keyframes[#keyframes].Time then
        local maxValue = keyframes[#keyframes].Value
        return { Left = maxValue, Right = maxValue, Alpha = 1}
    end
    
    local min, max

    for i = 2, #keyframes do
        if keyframes[i].Time > time then
            min = keyframes[i - 1]
            max = keyframes[i]
            break
        end
    end
    
    return {
        Left = min.Value,
        Right = max.Value,
        Alpha = (time - min.Time) / (max.Time - min.Time)
    }
end

---@generic T
---@param keyframes table[]
---@param time number
---@param defaultValue T
---@param mode InterpolationMode
---@param lerpFunction fun(a: T, b: T, t: number)
function PaletteKeyframes.Evaluate(keyframes, time, defaultValue, mode, lerpFunction)
    local segment = PaletteKeyframes.FindSegment(keyframes, time, defaultValue)

    if mode == "Fixed" then
        return segment.Left
    else
        return lerpFunction(segment.Left, segment.Right, segment.Alpha)
    end
end

return PaletteKeyframes

    end,

    ["palette_scripts.palette_over_lifetime"] = function()

---@class PaletteOverLifetime<T>
---@field Enabled boolean
---@field Mode InterpolationMode
---@field CurveMode CurveMode
---@field Keys Keyframe<T>[]
---@field KeysMin Keyframe<T>[]
---@field KeysMax Keyframe<T>[]
---@field DefaultValue T
local PaletteOverLifetime = {}
PaletteOverLifetime.__index = PaletteOverLifetime

local PaletteKeyframes = include("palette_scripts.palette_keyframes")
local PaletteUtils = include("palette_scripts.palette_utils")

---@generic T
---@param defaultValue T
---@return PaletteOverLifetime<T>
function PaletteOverLifetime.New(defaultValue)
    ---@type PaletteOverLifetime<T>
    local self = {
        Enabled = false,
        Mode = "Blend",
        CurveMode = "Single",
        Keys = {
            { Time = 0, Value = PaletteUtils.CopyValue(defaultValue) },
            { Time = 1, Value = PaletteUtils.CopyValue(defaultValue) }
        },
        KeysMin = {
            { Time = 0, Value = PaletteUtils.CopyValue(defaultValue) },
            { Time = 1, Value = PaletteUtils.CopyValue(defaultValue) }
        },
        KeysMax = {
            { Time = 0, Value = PaletteUtils.CopyValue(defaultValue) },
            { Time = 1, Value = PaletteUtils.CopyValue(defaultValue) }
        },
        DefaultValue = PaletteUtils.CopyValue(defaultValue)
    }
    
    return setmetatable(self, PaletteOverLifetime)
end

---@generic T
---@param time number
---@param lerpFactor number
---@return T
function PaletteOverLifetime:Evaluate(time, lerpFactor)
    if self.CurveMode == "Single" then
        return PaletteKeyframes.Evaluate(
            self.Keys,
            time,
            self.DefaultValue,
            self.Mode,
            PaletteUtils.Lerp
        )
    else
        local min = PaletteKeyframes.Evaluate(
            self.KeysMin,
            time,
            self.DefaultValue,
            self.Mode,
            PaletteUtils.Lerp
        )
        local max = PaletteKeyframes.Evaluate(
            self.KeysMax,
            time,
            self.DefaultValue,
            self.Mode,
            PaletteUtils.Lerp
        )

        return PaletteUtils.Lerp(min, max, lerpFactor)
    end
end

return PaletteOverLifetime


    end,

    ["palette_scripts.palette_shape"] = function()

local PaletteShape = {}

local PaletteUtils = include("palette_scripts.palette_utils")

---@param shape PaletteShapeConfig
---@param emitterPosition Vector
---@param orientation number
---@return Vector
function PaletteShape.GetSpawnPosition(shape, emitterPosition, orientation)
    if shape.EmitFrom ~= "Area" and shape.EmitFrom ~= "Edge" then
        error("Invalid EmitFrom: " .. shape.EmitFrom)
    end

    if shape.Type == "Point" then
        return emitterPosition
    elseif shape.Type == "Circle" then
        -- Inverse Transform Sampling so we can generate a position uniformly distributed inside
        -- the circle's thickness.
        local u = PaletteUtils.GetRandom()
        local minRadius = shape.Radius * (1 - shape.RadiusThickness)
        local chosenRadius = math.sqrt(minRadius^2 + u * (shape.Radius^2 - minRadius^2))
        local angle = math.rad(PaletteUtils.GetRandomFloat(0, shape.Arc) + orientation)

        return emitterPosition + Vector(
            chosenRadius * math.cos(angle),
            chosenRadius * math.sin(angle)
        )
    elseif shape.Type == "Rectangle" then
        local randX = PaletteUtils.GetRandomFloat(-shape.Size.X / 2, shape.Size.X / 2)
        local randY = PaletteUtils.GetRandomFloat(-shape.Size.Y / 2, shape.Size.Y / 2)

        if shape.EmitFrom == "Edge" then
            -- Weight each pair of edges by its length for uniform perimeter sampling.
            local choice = PaletteUtils.GetRandomFloat(0, shape.Size.X + shape.Size.Y)

            if choice < shape.Size.X then
                randY = PaletteUtils.GetRandom() < 0.5 and -shape.Size.Y / 2 or shape.Size.Y / 2
            else
                randX = PaletteUtils.GetRandom() < 0.5 and -shape.Size.X / 2 or shape.Size.X / 2
            end
        end

        local offset = Vector(randX, randY):Rotated(orientation)

        return emitterPosition + offset
    elseif shape.Type == "Triangle" then
        if #shape.Vertices < 3 then
            error("A particle emitter must have at least 3 vertices!")
        end
        
        local a, b, c = shape.Vertices[1], shape.Vertices[2], shape.Vertices[3]

        if shape.EmitFrom == "Edge" then
            local lengthAB = (a - b):Length()
            local lengthBC = (b - c):Length()
            local lengthCA = (c - a):Length()
            local perimeter = lengthAB + lengthBC + lengthCA
            local u = PaletteUtils.GetRandom()

            local choice = PaletteUtils.GetRandomFloat(0, perimeter)
            local startVertex, endVertex

            if choice < lengthAB then
                startVertex = a
                endVertex = b
            elseif choice < lengthAB + lengthBC then
                startVertex = b
                endVertex = c
            else
                startVertex = c
                endVertex = a
            end

            local point = startVertex + u * (endVertex - startVertex)
            point = point:Rotated(orientation)

            return emitterPosition + point
        else
            local u, v = PaletteUtils.GetRandom(), PaletteUtils.GetRandom()

            -- Uniform triangle sampling (baycentric coordinates)
            if u + v > 1 then
                u = 1 - u
                v = 1 - v
            end

            local point =  a + u * (b - a) + v * (c - a)
            local offset = point:Rotated(orientation)
            return emitterPosition + offset
        end
    elseif shape.Type == "Line" then
        local u = PaletteUtils.GetRandom()
        local randLength = PaletteUtils.GetRandomFloat(-shape.Length / 2, shape.Length / 2)
        local point = Vector(randLength * u, 0):Rotated(orientation)
        return emitterPosition + point
    else
        error("Unsupported particle shape: " .. shape.Type)
    end
end


---@param shape PaletteShapeConfig
---@param emitterPosition Vector
---@param startPosition Vector
---@param startDirection Vector
---@return Vector
function PaletteShape.GetDirection(shape, emitterPosition, startPosition, startDirection)
    if shape.DirectionMode == "Default" then
        return Vector(startDirection.X, startDirection.Y)
    elseif shape.DirectionMode == "Radial" then
        local vec = startPosition - emitterPosition

        if vec:LengthSquared() == 0 then
            return Vector(startDirection.X, startDirection.Y)
        end

        return vec:Normalized()
    else
        error("Unsupported shape direction mode: " .. tostring(shape.DirectionMode))
    end
end

return PaletteShape


    end,

}


include = function(name)
    local module = modules[name]
    assert(module, "Unknown bundled module: " .. tostring(name))
    return module()
end


local Palette = {}
local ParticleEmitter = include("palette_scripts.particle_emitter")
local PaletteOverLifetime = include("palette_scripts.palette_over_lifetime")
local PaletteGradient = include("palette_scripts.palette_gradient")

local initialized = false

---@type ParticleEmitter[]
local emitters = {}

local function onPostRoomRenderEntities()
    for _, particleEmitter in ipairs(emitters) do
        particleEmitter:_OnPostRoomEntitiesRender()
    end
end

local function onPreBackdropRenderWalls()
    for _, particleEmitter in ipairs(emitters) do
        particleEmitter:_OnPreBackdropRenderWalls()
    end
end

local function onPostUpdate()
    for _, particleEmitter in ipairs(emitters) do
        particleEmitter:Update()
    end
end

---@param emitter ParticleEmitter
local function unregisterEmitter(emitter)
    for i, registeredEmitter in ipairs(emitters) do
        if registeredEmitter == emitter then
            table.remove(emitters, i)
            return
        end
    end
end

local function destroyNonPersistentEmitters()
    -- We loop through the emitters backwards since calling :Destroy() on one will cause the 
    -- `emitters` table to shift due to a call to `table.remove`.
    for i = #emitters, 1, -1 do
        local emitter = emitters[i]
        if not emitter.PersistAcrossRooms then
            emitter:Destroy()
        end
    end
end

--- Initializes Palette using the provided `mod`. Errors if Palette has already been registered.
---@param mod ModReference
function Palette:Init(mod)
    assert(not initialized, "Palette has already been initialized")
    
    initialized = true

    mod:AddCallback(ModCallbacks.MC_PRE_BACKDROP_RENDER_WALLS, onPreBackdropRenderWalls)
    mod:AddCallback(ModCallbacks.MC_POST_ROOM_RENDER_ENTITIES, onPostRoomRenderEntities)
    mod:AddCallback(ModCallbacks.MC_POST_UPDATE, onPostUpdate)
    mod:AddCallback(ModCallbacks.MC_PRE_NEW_ROOM, destroyNonPersistentEmitters)
    mod:AddCallback(ModCallbacks.MC_PRE_GAME_EXIT, destroyNonPersistentEmitters)
end

--- Creates a new `ParticleEmitter`.
---@param texturePath string The file path pointing to the texture used for the emitted particles. It must be a `.png` file with a bit-depth of 32. Invalid file paths will cause an error.
---@param position Vector | nil Optional. The starting position of the emitter. Default is (0, 0)
---@return ParticleEmitter
function Palette:CreateParticleEmitter(texturePath, position)
    assert(initialized, "Palette must be initialized first before calling `CreateParticleEmitter`")

    if not position then
        position = Vector.Zero
    else
        position = Vector(position.X, position.Y)
    end

    ---@cast position Vector
        
    local image = Renderer.LoadImage(texturePath)
    local sourceQuad = SourceQuad.NewFromRectangle(Vector.Zero, image:GetWidth(), image:GetHeight())

    ---@type ParticleEmitter
    local ParticleEmitterInstance = {
        IsWorldSpace = true,
        Position = position,
        MaxParticles = 100,
        Lifetime = 60,
        ParticleRate = 5,
        StartColor = KColor.White,
        ColorOverLifetime = {
            Enabled = false,
            CurveMode = "Single",
            Mode = "Blend",
            Gradient = PaletteGradient:New(),
            GradientMin = PaletteGradient:New(),
            GradientMax = PaletteGradient:New()
        },
        VelocityOverLifetime = {
            Enabled = false,
            Space = "Local",
            LinearVelocity = Vector.Zero,
            OrbitalVelocity = 0,
            OrbitalOffset = Vector.Zero,
            Radial = 0,
            SpeedModifier = 1,
        },
        Orientation = 0,
        StartSpeed = 2,
        StartDirection = Vector(0, -1),
        StartSize = Vector.One,
        StartRotation = 0,
        PersistAcrossRooms = false,
        DirectionSpread = 0,
        SizeOverLifetime = PaletteOverLifetime.New(Vector.One),
        RotationOverLifetime = PaletteOverLifetime.New(0),
        Shape = {
            Type = "Point",
            Radius = 40,
            RadiusThickness = 1,
            Arc = 360,
            Size = Vector.One,
            DirectionMode = "Default",
            EmitFrom = "Area",
            Vertices = {
                Vector(-50, 30),
                Vector(50, 30),
                Vector(0, -60)
            },
            Length = 120
        },
        RenderMode = "AboveEntities",

        _IsDestroyed = false,
        _EmissionAccumulator = 0,
        _IsEmitting = true,
        _Particles = {},
        _ParticlePool = {},
        _RenderImage = image,
        _EmitterSourceQuad = sourceQuad,
        _DestroyFun = unregisterEmitter,
    }

    local ParticleEmitterMT = setmetatable(ParticleEmitterInstance, ParticleEmitter)

    ---@cast ParticleEmitterMT ParticleEmitter
    table.insert(emitters, ParticleEmitterMT)

    return ParticleEmitterMT
end

return Palette

